public class Attributes {
    private Map<String, Object> values;

    public Attributes() {
        this.values = new HashMap<>();
    }

    public void put(String key, Object value) {
        if (!values.containsKey(key)) {
            values.put(key, value);
        } else {
            values.put(key, Arrays.asList((Object[]) values.get(key)));
            values.put(key, Arrays.asList(value));
        }
    }

    public boolean get(String key) {
        return (boolean) values.get(key);
    }

    public void putNullValue(String key, Object value) {
        if (!values.containsKey(key)) {
            values.put(key, value);
        } else {
            throw new RuntimeException("Key '" + key + "' already exists.");
        }
    }

    public String toString() {
        return Arrays.toString(values.values());
    }
}

public class TestAttributes extends TestCase {
    private Attributes attributes;

    public void setUp() {
        this.attributes = new Attributes();
    }

    public void testPutValue() {
        attributes.put("key", "value");
        assertEquals("1,2", (String) attributes.get("key"));
    }

    public void testGetKey() {
        assertEquals("value", (boolean) attributes.get("key"));
    }

    public void testPutNullValue() {
        attributes.putNullValue("key", null);
        assertEquals(null, (Object) attributes.get("key"));
    }
}
